# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student


def _make(last, first):
    return Student("id" + last, last, first, "A")


class SeatingTests(unittest.TestCase):
    def test_sorted_and_split_into_rows(self):
        people = [
            _make("Halloway", "Juno"),
            _make("Zed", "Amy"),
            _make("Dunmere", "Piet")
        ]
        self.assertEqual(
            seating_rows(people, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Zed, Amy"
            ]
        )

    def test_bad_seat_count_raises(self):
        people = [_make("Zed", "Amy")]
        for seats in (0, -1):
            with self.assertRaises(ValueError):
                seating_rows(people, seats)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 3)
